-- Ordonnance Mobile baseline schema.
-- This is the canonical application layer used by Patient, Hôpital,
-- Pharmacie and Admin. Existing legacy English tables are preserved until
-- the cut-over is validated.

create extension if not exists pgcrypto;

create table if not exists public.patients (id uuid primary key references auth.users(id) on delete cascade, nom text, prenom text, telephone text, email text, date_naissance date, sexe text, adresse text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.hopitaux (id bigint generated by default as identity primary key, nom text not null, adresse text, ville text default 'Lomé', telephone text, email text, latitude numeric, longitude numeric, photo_url text, statut text not null default 'en_attente', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.rendez_vous (id bigint generated by default as identity primary key, patient_id uuid not null references public.patients(id) on delete cascade, hopital_id bigint not null references public.hopitaux(id) on delete cascade, specialite text, motif text, date_rdv date, heure_rdv time, statut text not null default 'en_attente', priorite integer not null default 3, paiement_statut text default 'en_attente', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.constantes (id bigint generated by default as identity primary key, rendez_vous_id bigint references public.rendez_vous(id) on delete cascade, patient_id uuid references public.patients(id) on delete cascade, temperature text, tension text, poids numeric, taille numeric, pouls text, saturation text, notes text, created_at timestamptz not null default now());
create table if not exists public.ordonnances (id bigint generated by default as identity primary key, rendez_vous_id bigint references public.rendez_vous(id) on delete set null, patient_id uuid not null references public.patients(id) on delete cascade, hopital_id bigint references public.hopitaux(id) on delete set null, medecin_id uuid references auth.users(id) on delete set null, statut text not null default 'active', diagnostic text, instructions text, created_at timestamptz not null default now());
create table if not exists public.ordonnance_lignes (id bigint generated by default as identity primary key, ordonnance_id bigint not null references public.ordonnances(id) on delete cascade, produit text not null, dosage text, posologie text, duree text, quantite integer, created_at timestamptz not null default now());
create table if not exists public.produits_pharmacie (id bigint generated by default as identity primary key, pharmacie_id uuid not null references public.pharmacies(id) on delete cascade, nom text not null, description text, prix integer not null default 0, stock integer not null default 0, actif boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.commandes_pharmacie (id bigint generated by default as identity primary key, ordonnance_id bigint references public.ordonnances(id) on delete set null, ligne_id bigint references public.ordonnance_lignes(id) on delete set null, patient_id uuid not null references public.patients(id) on delete cascade, pharmacie_id uuid not null references public.pharmacies(id) on delete cascade, produit text not null, montant integer not null default 0, mode_paiement text, statut text not null default 'en_attente', code_retrait text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.ventes_comptoir (id bigint generated by default as identity primary key, pharmacie_id uuid not null references public.pharmacies(id) on delete cascade, produit_id bigint references public.produits_pharmacie(id) on delete set null, produit text, quantite integer not null default 1, montant integer not null default 0, mode_paiement text, created_at timestamptz not null default now());
create table if not exists public.resultats_analyses (id bigint generated by default as identity primary key, patient_id uuid not null references public.patients(id) on delete cascade, rendez_vous_id bigint references public.rendez_vous(id) on delete set null, type_analyse text, resultat text, fichier_url text, created_at timestamptz not null default now());
create table if not exists public.avis (id bigint generated by default as identity primary key, patient_id uuid references public.patients(id) on delete cascade, hopital_id bigint references public.hopitaux(id) on delete cascade, pharmacie_id uuid references public.pharmacies(id) on delete cascade, note integer check (note between 1 and 5), commentaire text, created_at timestamptz not null default now());

create index if not exists rendez_vous_patient_idx on public.rendez_vous(patient_id);
create index if not exists rendez_vous_hopital_idx on public.rendez_vous(hopital_id);
create index if not exists ordonnances_patient_idx on public.ordonnances(patient_id);
create index if not exists ordonnance_lignes_ordonnance_idx on public.ordonnance_lignes(ordonnance_id);
create index if not exists commandes_pharmacie_ordonnance_idx on public.commandes_pharmacie(ordonnance_id);
create index if not exists commandes_pharmacie_patient_idx on public.commandes_pharmacie(patient_id);
create index if not exists commandes_pharmacie_pharmacie_idx on public.commandes_pharmacie(pharmacie_id);

alter table public.patients enable row level security;
alter table public.hopitaux enable row level security;
alter table public.rendez_vous enable row level security;
alter table public.constantes enable row level security;
alter table public.ordonnances enable row level security;
alter table public.ordonnance_lignes enable row level security;
alter table public.produits_pharmacie enable row level security;
alter table public.commandes_pharmacie enable row level security;
alter table public.ventes_comptoir enable row level security;
alter table public.resultats_analyses enable row level security;
alter table public.avis enable row level security;

drop policy if exists patients_self on public.patients;
create policy patients_self on public.patients for all to authenticated using (id=auth.uid()) with check (id=auth.uid());
drop policy if exists hopitaux_public_select on public.hopitaux;
create policy hopitaux_public_select on public.hopitaux for select to anon, authenticated using (statut in ('publie','approuve'));
drop policy if exists rendez_vous_patient_all on public.rendez_vous;
create policy rendez_vous_patient_all on public.rendez_vous for all to authenticated using (patient_id=auth.uid()) with check (patient_id=auth.uid());
drop policy if exists ordonnances_patient_select on public.ordonnances;
create policy ordonnances_patient_select on public.ordonnances for select to authenticated using (patient_id=auth.uid());
drop policy if exists ordonnance_lignes_patient_select on public.ordonnance_lignes;
create policy ordonnance_lignes_patient_select on public.ordonnance_lignes for select to authenticated using (exists(select 1 from public.ordonnances o where o.id=ordonnance_id and o.patient_id=auth.uid()));
drop policy if exists commandes_patient_all on public.commandes_pharmacie;
create policy commandes_patient_all on public.commandes_pharmacie for all to authenticated using (patient_id=auth.uid()) with check (patient_id=auth.uid());
drop policy if exists resultats_patient_all on public.resultats_analyses;
create policy resultats_patient_all on public.resultats_analyses for all to authenticated using (patient_id=auth.uid()) with check (patient_id=auth.uid());
drop policy if exists avis_patient_all on public.avis;
create policy avis_patient_all on public.avis for all to authenticated using (patient_id=auth.uid()) with check (patient_id=auth.uid());
